package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func skipSpace() bool {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	return pos < len(data)
}

func token() string {
	skipSpace()
	s := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[s:pos])
}

func num() int64 {
	skipSpace()
	neg := false
	if pos < len(data) && (data[pos] == '-' || data[pos] == '+') {
		neg = data[pos] == '-'
		pos++
	}
	var v int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		v = v*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := num()
	h := make([]int64, n)
	var top int64
	for i := range h {
		h[i] = num()
		top = max(top, h[i])
	}
	// ok(s): some run of at least s consecutive buildings all have height >= s.
	ok := func(s int64) bool {
		var run int64
		for _, x := range h {
			if x >= s {
				run++
			} else {
				run = 0
			}
			if run >= s {
				return true
			}
		}
		return s == 0
	}
	lo, hi := int64(0), min(n, top)
	for lo < hi {
		mid := (lo + hi + 1) / 2
		if ok(mid) {
			lo = mid
		} else {
			hi = mid - 1
		}
	}
	fmt.Println(lo * lo)
}
